                assert_eq!(map.len(), keys.len());
                assert!(map.keys().copied().eq(keys.iter().copied()));
                for (index, key) in keys.iter().enumerate() {
                    let expected = if index < retained {
                        200
                    } else {
                        u16::from(*key) + 100
                    };
                    assert_eq!(map.get(key), Some(&expected));
                    assert!(map.contains_key(key));
                }
            }
        }
    }

